import{z as o,x as A,o as i,c as p,q as t,j as s,D as e,d as n,s as r,S as l}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"LSM 与 SELinux","description":"","frontmatter":{"title":"LSM 与 SELinux","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lsm-selinux.md","filePath":"cs/lsm-selinux.md","lastUpdated":1791063341000}'),d={name:"cs/lsm-selinux.md"};function c(u,a,B,S,_,x){const E=A("Mermaid");return i(),p("div",null,[a[2]||(a[2]=t('<h1 id="lsm-与-selinux" tabindex="-1">LSM 与 SELinux <a class="header-anchor" href="#lsm-与-selinux" aria-label="Permalink to &quot;LSM 与 SELinux&quot;">​</a></h1><div class="epigraph"><p>LSM 在 inode、进程、套接字等对象上留钩子；SELinux 用类型强制把「谁能碰谁」写成策略，而不是再加一位 cap。</p><footer>—— 据 Wright et al., Linux Security Modules；NSA/SELinux 文档；[xattr](/cs/xattr-acl) 为标签存放先修</footer></div><p><a href="/cs/linux-capabilities">capabilities</a> 仍是「能做特权操作吗」。强制访问要问 <strong>这个 httpd 能不能写那个 shadow</strong>。缺口是 LSM 框架与 SELinux 作为实例。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>钩子：<code>inode_permission</code>、<code>file_open</code>、<code>socket_connect</code>… 多个 LSM 可叠（新内核）。SELinux：类型、域转换、<code>security.*</code> xattr。缺口：策略语言不是本课作业；Permissive vs Enforcing；与 <a href="/cs/overlayfs">overlay</a> 标签 copy-up。本课不写如何破解 SELinux。</p><p><span class="marginnote">直觉类比：SELinux 给每个进程、每个文件都挂「类型名牌」，再立一部规则手册——只有写明「A 类可碰 B 类」的组合才放行。普通 rwx 权限只是第一道闸，名牌对不上照样拦，这就是「类型强制」四个字的全部意思。</span></p><p><span class="marginnote">AppArmor 下一课用路径。SELinux 用类型，与 inode 绑定更紧。audit 后课记拒绝。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>打开文件：VFS 权限 → LSM 钩 → SELinux 查 AVC 缓存。对照 <a href="/cs/netfilter-conntrack">netfilter</a>：一个管包，一个管对象标签。对照 ASan：一个防内存 bug，一个防越权。对照 FUSE：用户 FS 也要过钩。</p><p><span class="marginnote">术语翻译：AVC（Access Vector Cache）就是「最近判定的小抄」——查一次策略要搜规则库，内核把刚用过的结论（如 httpd_t 可写 var_log_t）缓在内存里，同一问题再问直接命中；策略改了要刷新缓存才生效。</span></p>',10)),(i(),s(l,null,{default:e(()=>[r(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYS%5B%22%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%22%5D%20--%3E%20VFS%5B%22DAC%22%5D%0A%20%20VFS%20--%3E%20LSM%5B%22LSM%20%E9%92%A9%22%5D%0A%20%20LSM%20--%3E%20AVC%5B%22SELinux%20AVC%22%5D%0A%20%20AVC%20--%3E%7C%22%E6%8B%92%E7%BB%9D%22%7C%20EACCES%5B%22EACCES%20%E5%B9%B6%20audit%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>LSM 让强制策略成为内核可插层，SELinux 把系统做成类型图。它不替代补丁。不要写成合规广告。与 <a href="/cs/kpti-os">KPTI</a>：正交。与容器：需正确 label 与类别。</p><p>策略错误会拒绝合法服务，看起来像权限 bug。</p><p>实现上：AVC 缓存命中才快，首次决策要走策略。域转换在 exec 时发生，httpd 的子进程类型由策略决定。Permissive 只记不拦，容易误以为已经保护。 读法上只引用<a href="/cs/linux-capabilities">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p><span class="marginnote">常见误区：初学者容易以为「装了 SELinux 就安全了」。Permissive 模式只记日志不拦截；Enforcing 下策略没写到的访问默认全拒，可能把服务拒瘫——「明明权限对却启动失败」多半是 SELinux 拒绝，先翻 audit 日志再怀疑文件系统。</span></p>',5)),(i(),s(l,null,{default:e(()=>[r(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUBJ%5B%22%E4%B8%BB%E4%BD%93%3A%20%E8%BF%9B%E7%A8%8B%E5%9F%9F%20httpd_t%22%5D%20--%3E%20OP%5B%22%E6%93%8D%E4%BD%9C%3A%20%E5%86%99%20%2Fetc%2Fshadow%22%5D%0A%20%20XATTR%5B%22%E6%96%87%E4%BB%B6%E7%B1%BB%E5%9E%8B%20shadow_t%20%E5%AD%98%E4%BA%8E%20xattr%22%5D%20--%3E%20LOOK%0A%20%20OP%20--%3E%20LOOK%7B%22allow%20%E8%A7%84%E5%88%99%3A%20httpd_t%20%E5%8F%AF%E5%86%99%20shadow_t%20%3F%22%7D%0A%20%20LOOK%20--%3E%7C%22%E6%97%A0%E6%AD%A4%E8%A7%84%E5%88%99%22%7C%20DENY%5B%22%E6%8B%92%E7%BB%9D%20%2B%20audit%20%E6%97%A5%E5%BF%97%22%5D%0A%20%20LOOK%20--%3E%7C%22%E6%9C%89%22%7C%20AVC2%5B%22AVC%20%E5%91%BD%E4%B8%AD%2C%20%E6%94%BE%E8%A1%8C%22%5D%0A%20%20EXECP%5B%22exec%20%E6%96%B0%E7%A8%8B%E5%BA%8F%22%5D%20--%3E%20TRAN%7B%22%E7%AD%96%E7%95%A5%E6%9C%89%E5%9F%9F%E8%BD%AC%E6%8D%A2%E8%A7%84%E5%88%99%3F%22%7D%0A%20%20TRAN%20--%3E%7C%22%E6%9C%89%22%7C%20SWITCH%5B%22%E5%AD%90%E8%BF%9B%E7%A8%8B%E6%8D%A2%E5%9F%9F%2C%20%E5%A6%82%20init_t%20%E2%86%92%20httpd_t%22%5D%0A%20%20TRAN%20--%3E%7C%22%E6%97%A0%22%7C%20SAME%5B%22%E5%AD%90%E8%BF%9B%E7%A8%8B%E6%B2%BF%E7%94%A8%E7%88%B6%E5%9F%9F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>LSM 与 SELinux</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MLS 等级的全部。不保证微内核的同构。下一课路径强制：AppArmor。</p><p>版本字段会变，课序钉的是机制对象「LSM 与 SELinux」，不是某一主线内核的结构体名。 后课默认：对象可打类型，钩子强制。按路径的 MAC，下一课 AppArmor。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LSM 提供钩；SELinux 用类型强制。</li><li>标签常在 xattr；拒绝进 audit。</li><li>AppArmor 是下一课。</li><li>出处：Wright LSM；SELinux；Linux security。</li></ul>',7))])}const L=o(d,[["render",c]]);export{m as __pageData,L as default};
